def minNumberOfSemesters(n: int, relations: list[list[int]], k: int) -> int:
    prereq = [0] * n
    for u, v in relations:
        prereq[v - 1] |= (1 << (u - 1))
    dp = [float('inf')] * (1 << n)
    dp[0] = 0
    for mask in range(1 << n):
        if dp[mask] == float('inf'): continue
        available = 0
        for i in range(n):
            if not (mask & (1 << i)) and (mask & prereq[i]) == prereq[i]:
                available |= (1 << i)
        avail_list = [i for i in range(n) if (available & (1 << i))]
        from itertools import combinations
        if len(avail_list) <= k:
            nxt = mask | available
            dp[nxt] = min(dp[nxt], dp[mask] + 1)
        else:
            for comb in combinations(avail_list, k):
                submask = sum(1 << i for i in comb)
                nxt = mask | submask
                dp[nxt] = min(dp[nxt], dp[mask] + 1)
    return dp[(1 << n) - 1]

